import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"DevOps y despliegue — Cinco plataformas, un comando","description":"HF Spaces, Railway, Render, Fly.io, Koyeb, Cloudflare Workers — desplegar servicios resilientes en tiers gratuitos.","frontmatter":{"title":"DevOps y despliegue — Cinco plataformas, un comando","description":"HF Spaces, Railway, Render, Fly.io, Koyeb, Cloudflare Workers — desplegar servicios resilientes en tiers gratuitos."},"headers":[],"relativePath":"es/skills/devops/index.md","filePath":"es/skills/devops/index.md"}`),a={name:`es/skills/devops/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="devops-y-despliegue-—-cinco-plataformas-un-comando" tabindex="-1">DevOps y despliegue — Cinco plataformas, un comando <a class="header-anchor" href="#devops-y-despliegue-—-cinco-plataformas-un-comando" aria-label="Permalink to “DevOps y despliegue — Cinco plataformas, un comando”">​</a></h1><p>El despliegue es donde los hobbies se vuelven productos. Mantengo rutas de despliegue en seis plataformas y trato &quot;un comando&quot; como un requisito estricto — porque cuando una plataforma se vuelve hostil o una región se cae, la velocidad de migración <em>es</em> el uptime.</p><h2 id="manual-de-plataformas" tabindex="-1">Manual de plataformas <a class="header-anchor" href="#manual-de-plataformas" aria-label="Permalink to “Manual de plataformas”">​</a></h2><table tabindex="0"><thead><tr><th>Plataforma</th><th>Lo que corro allí</th></tr></thead><tbody><tr><td>Hugging Face Spaces</td><td>Hermes Stack, puentes de IA — cómputo gratuito generoso.</td></tr><tr><td>Cloudflare Workers</td><td>Paneles usf-edge — estado KV, 300+ PoPs, sin arranques en frío.</td></tr><tr><td>Railway / Render / Fly.io / Koyeb</td><td>Paneles y APIs — cada uno con sus propias rarezas antibloqueo.</td></tr><tr><td>VPS (Linux)</td><td>Despliegues clásicos, túneles, monitoreo.</td></tr></tbody></table><ul><li><strong>Docker</strong> cuando la plataforma lo soporta; <strong>Procfiles y buildpacks</strong> cuando no.</li><li><strong>Hábitos de CI</strong> — GitHub Actions para tests y builds; los despliegues se mantienen aburridos a propósito.</li><li><strong>Observabilidad</strong> — logs estructurados, pings de uptime desde mi propia herramienta, alertas a Telegram.</li><li><strong>Disciplina de secretos</strong> — variables de entorno, bóvedas cifradas, nada en git.</li></ul><p>La filosofía coincide con mi <a href="/Usf/es/about/networking/">mentalidad de redes</a>: cada despliegue está a un derribo de morir, así que cada despliegue tiene un gemelo documentado en otra plataforma. Mis paneles literalmente traen cinco comandos de despliegue por esta razón.</p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};